package GeneratedModel {
  private import ScalarValues::*;
  part def Controller {
    in attribute io_8 : Integer;
    attribute servoAngleAccumMs : Integer := 0;
    attribute servoAngle1 : Real := 0.0;
    attribute servoAngle2 : Real := 0.0;
    perform action tick {
      first start;
      then assign servoAngleAccumMs := servoAngleAccumMs + io_8;
      then if servoAngleAccumMs >= 2000 {
        first start;
        then assign servoAngleAccumMs := servoAngleAccumMs - 2000;
        then if servoAngle1 >= 180.0 {
          first start;
          then assign servoAngle1 := 0.0;
          then assign servoAngle2 := 0.0;
        } else {
          first start;
          then assign servoAngle1 := servoAngle1 + 30.0;
          then assign servoAngle2 := servoAngle2 + 30.0;
        }
        then if servoAngle1 >= 180.0 {
          first start;
          then assign servoAngle1 := 0.0;
          then assign servoAngle2 := 0.0;
        }
      }
      then if servoAngle1 == 0.0 {
        first start;
        then assign servoAngle2 := 0.0;
      }
    }
    out attribute io_0 : Real = servoAngle1;
    out attribute io_1 : Real = servoAngle2;
